class Solution {
  public String getSmallestString(String s) {
    char[] a = s.toCharArray();
    for (int i = 0; i + 1 < a.length; i++) {
      if (a[i] > a[i + 1] && ((a[i] - '0') & 1) == ((a[i + 1] - '0') & 1)) {
        char t = a[i];
        a[i] = a[i + 1];
        a[i + 1] = t;
        break;
      }
    }
    return new String(a);
  }
}
